import{_ as n,a0 as c,w as r,s,ao as a,I as l,x as o,a1 as t,A as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"你必须了解的基础的 Linux 网络命令 | LCTT x X-CMD","titleTemplate":false,"description":"你必须了解的基础的 Linux 网络命令 | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"你必须了解的基础的 Linux 网络命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"你必须了解的基础的 Linux 网络命令 | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160621 Basic Linux Networking Commands You Should Know","title":"你必须了解的基础的 Linux 网络命令","tag":"201609","desc":""},"relativePath":"201609/20160621 Basic Linux Networking Commands You Should Know.md","filePath":"[post].md"}'),u={name:"201609/20160621 Basic Linux Networking Commands You Should Know.md"};function p(m,e,P,f,h,g){const i=c("Link");return r(),s("div",null,[e[21]||(e[21]=a('<h1 id="你必须了解的基础的-linux-网络命令" tabindex="-1">你必须了解的基础的 Linux 网络命令 <a class="header-anchor" href="#你必须了解的基础的-linux-网络命令" aria-label="Permalink to “你必须了解的基础的 Linux 网络命令”">​</a></h1><p><img src="https://itsfoss.com/wp-content/uploads/2016/06/Basic-Networking-Commands-Linux.jpg" alt=""></p><blockquote><p>摘要：有抱负的 Linux 系统管理员和 Linux 狂热者必须知道的、最重要的、而且基础的 Linux 网络命令合集。</p></blockquote><p>在 It’s FOSS 我们并非每天都谈论 Linux 的“命令行方面”。基本上，我更专注于 Linux 的桌面端。但你们读者中的一些人在内部调查（仅面向 It&#39;s FOSS newsletter 订阅者）中指出，你们也想学些命令行技巧。速查表也受大部分读者所喜欢和支持。</p><p>为此，我编辑了一个 Linux 中基础网络命令的列表。它并不是一个教你如何使用这些命令的教程，而是一个命令合集和他们的简短解释。所以，如果你已经使用过这些命令，你可以用它来快速记住命令。</p><p>你可以把这个网页添加为书签以便快速查阅，或输出一个 PDF 版本以便离线使用。</p><p>当我还是通信系统工程专业的学生的时候我就有这个 Linux 网络命令的列表了。它帮助我在计算机网络课程获得了高分。希望它也能以同样的方式帮助你。</p><h3 id="linux-基础网络命令列表" tabindex="-1">Linux 基础网络命令列表 <a class="header-anchor" href="#linux-基础网络命令列表" aria-label="Permalink to “Linux 基础网络命令列表”">​</a></h3><p>我在计算机网络课程上使用 FreeBSD，不过这些 UNIX 命令应该也能在 Linux 上同样工作。</p><h4 id="连通性" tabindex="-1">连通性 <a class="header-anchor" href="#连通性" aria-label="Permalink to “连通性”">​</a></h4>',10)),l("ul",null,[e[7]||(e[7]=l("li",null,[l("code",null,"ping <host>"),o("：发送 ICMP echo 消息（一个包）到主机。这可能会不停地发送直到你按下 "),l("code",null,"Control-C"),o("。Ping 的通意味着一个包从你的机器通过 ICMP 发送出去，并在 IP 层回显。Ping 告诉你另一个主机是否在运行。")],-1)),l("li",null,[e[5]||(e[5]=l("code",null,"telnet <host> [port]",-1)),e[6]||(e[6]=o("：与主机在指定的端口通信。默认的 telnet 端口是 23。按 Control-] 以退出 telnet。其它一些常用的端口是： ",-1)),l("ul",null,[e[3]||(e[3]=l("li",null,"7 —— echo 端口",-1)),e[4]||(e[4]=l("li",null,"25 —— SMTP，用于发送邮件",-1)),l("li",null,[e[1]||(e[1]=o("79 —— Finger (LCTT 译注：",-1)),t(i,{href:"https://en.wikipedia.org/wiki/Finger_protocol"},{default:d(()=>[...e[0]||(e[0]=[o("维基百科 - Finger protocal",-1)])]),_:1}),e[2]||(e[2]=o("，不过举例 Finger 恐怕不合时宜，倒不如试试 80？），提供该网络下其它用户的信息。",-1))])])])]),e[22]||(e[22]=a('<h4 id="arp" tabindex="-1">ARP <a class="header-anchor" href="#arp" aria-label="Permalink to “ARP”">​</a></h4><p>ARP 用于将 IP 地址转换为以太网地址。root 用户可以添加和删除 ARP 记录。当 ARP 记录被污染或者错误时，删除它们会有用。root 显式添加的 ARP 记录是永久的 —— 代理设置的也是。ARP 表保存在内核中，动态地被操作。ARP 记录会被缓存，通常在 20 分钟后失效并被删除。</p><ul><li><code>arp -a</code>：打印 ARP 表。</li><li><code>arp -s &lt;ip_address&gt; &lt;mac_address&gt; [pub]</code>：添加一条记录到表中。</li><li><code>arp -a -d</code>：删除 ARP 表中的所有记录。</li></ul><h4 id="路由" tabindex="-1">路由 <a class="header-anchor" href="#路由" aria-label="Permalink to “路由”">​</a></h4><ul><li><code>netstat -r</code>：打印路由表。路由表保存在内核中，用于 IP 层把包路由到非本地网络。</li><li><code>route add</code>：route 命令用于向路由表添加静态（手动指定而非动态）路由路径。所有从该 PC 到那个 IP/子网的流量都会经由指定的网关 IP。它也可以用来设置一个默认路由。例如，在 IP/子网处使用 0.0.0.0，就可以发送所有包到特定的网关。</li><li><code>routed</code>：控制动态路由的 BSD 守护程序。开机时启动。它运行 RIP 路由协议。只有 root 用户可用。没有 root 权限你不能运行它。</li><li><code>gated</code>：gated 是另一个使用 RIP 协议的路由守护进程。它同时支持 OSPF、EGP 和 RIP 协议。只有 root 用户可用。</li><li><code>traceroute</code>：用于跟踪 IP 包的路由。它每次发送包时都把跳数加 1，从而使得从源地址到目的地之间的所有网关都会返回消息。</li><li><code>netstat -rnf inet</code>：显示 IPv4 的路由表。</li><li><code>sysctl net.inet.ip.forwarding=1</code>：启用包转发（把主机变为路由器）。</li><li><code>route add|delete [-net|-host] &lt;destination&gt; &lt;gateway&gt;</code>：（如 <code>route add 192.168.20.0/24 192.168.30.4</code>）添加一条路由。</li><li><code>route flush</code>：删除所有路由。</li><li><code>route add -net 0.0.0.0 192.168.10.2</code>：添加一条默认路由。</li><li><code>routed -Pripv2 -Pno_rdisc -d [-s|-q]</code>：运行 routed 守护进程，使用 RIPv2 协议，不启用 ICMP 自动发现，在前台运行，供给模式或安静模式。</li><li><code>route add 224.0.0.0/4 127.0.0.1</code>：为本地地址定义多播路由。（LCTT 译注：原文存疑）</li><li><code>rtquery -n &lt;host&gt;</code>（LCTT 译注：增加了 host 参数）：查询指定主机上的 RIP 守护进程（手动更新路由表）。</li></ul><h4 id="其它" tabindex="-1">其它 <a class="header-anchor" href="#其它" aria-label="Permalink to “其它”">​</a></h4><ul><li><code>nslookup</code>：向 DNS 服务器查询，将 IP 转为名称，或反之。例如，<code>nslookup facebook.com</code> 会给出 facebook.com 的 IP。</li><li><code>ftp &lt;host&gt; [port]</code>（LCTT 译注：原文中 water 应是笔误）：传输文件到指定主机。通常可以使用 登录名 &quot;anonymous&quot; , 密码 &quot;guest&quot; 来登录。</li><li><code>rlogin -l &lt;host&gt;</code>（LCTT 译注：添加了 host 参数）：使用类似 telnet 的虚拟终端登录到主机。</li></ul><h4 id="重要文件" tabindex="-1">重要文件 <a class="header-anchor" href="#重要文件" aria-label="Permalink to “重要文件”">​</a></h4><ul><li><code>/etc/hosts</code>：域名到 IP 地址的映射。</li><li><code>/etc/networks</code>：网络名称到 IP 地址的映射。</li><li><code>/etc/protocols</code>：协议名称到协议编号的映射。</li><li><code>/etc/services</code>：TCP/UDP 服务名称到端口号的映射。</li></ul><h4 id="工具和网络性能分析" tabindex="-1">工具和网络性能分析 <a class="header-anchor" href="#工具和网络性能分析" aria-label="Permalink to “工具和网络性能分析”">​</a></h4><ul><li><code>ifconfig &lt;interface&gt; &lt;address&gt; [up]</code>：启动接口。</li><li><code>ifconfig &lt;interface&gt; [down|delete]</code>：停止接口。</li><li><code>ethereal &amp;</code>：在后台打开 <code>ethereal</code> 而非前台。</li><li><code>tcpdump -i -vvv</code>：抓取和分析包的工具。</li><li><code>netstat -w [seconds] -I [interface]</code>：显示网络设置和统计信息。</li><li><code>udpmt -p [port] -s [bytes] target_host</code>：发送 UDP 流量。</li><li><code>udptarget -p [port]</code>：接收 UDP 流量。</li><li><code>tcpmt -p [port] -s [bytes] target_host</code>：发送 TCP 流量。</li><li><code>tcptarget -p [port]</code>：接收 TCP 流量。</li></ul><h4 id="交换机" tabindex="-1">交换机 <a class="header-anchor" href="#交换机" aria-label="Permalink to “交换机”">​</a></h4><ul><li><code>ifconfig sl0 srcIP dstIP</code>：配置一个串行接口（在此前先执行 <code>slattach -l /dev/ttyd0</code>，此后执行 <code>sysctl net.inet.ip.forwarding=1</code>）</li><li><code>telnet 192.168.0.254</code>：从子网中的一台主机访问交换机。</li><li><code>sh ru</code> 或 <code>show running-configuration</code>：查看当前配置。</li><li><code>configure terminal</code>：进入配置模式。</li><li><code>exit</code>：退出当前模式。（LCTT 译注：原文存疑）</li></ul><h4 id="vlan" tabindex="-1">VLAN <a class="header-anchor" href="#vlan" aria-label="Permalink to “VLAN”">​</a></h4><ul><li><code>vlan n</code>：创建一个 ID 为 n 的 VLAN。</li><li><code>no vlan N</code>：删除 ID 为 n 的 VLAN。</li><li><code>untagged Y</code>：添加端口 Y 到 VLAN n。</li><li><code>ifconfig vlan0 create</code>：创建 vlan0 接口。</li><li><code>ifconfig vlan0 vlan_ID vlandev em0</code>：把 em0 加入到 vlan0 接口（LCTT 译注：原文存疑），并设置标记为 ID。</li><li><code>ifconfig vlan0 [up]</code>：启用虚拟接口。</li><li><code>tagged Y</code>：为当前 VLAN 的端口 Y 添加标记帧支持。</li></ul><h4 id="udp-tcp" tabindex="-1">UDP/TCP <a class="header-anchor" href="#udp-tcp" aria-label="Permalink to “UDP/TCP”">​</a></h4><ul><li><code>socklab udp</code>：使用 UDP 协议运行 <code>socklab</code>。</li><li><code>sock</code>：创建一个 UDP 套接字，等效于输入 <code>sock udp</code> 和 <code>bind</code>。</li><li><code>sendto &lt;Socket ID&gt; &lt;hostname&gt; &lt;port #&gt;</code>：发送数据包。</li><li><code>recvfrom &lt;Socket ID&gt; &lt;byte #&gt;</code>：从套接字接收数据。</li><li><code>socklab tcp</code>：使用 TCP 协议运行 <code>socklab</code>。</li><li><code>passive</code>：创建一个被动模式的套接字，等效于 <code>socklab</code>，<code>sock tcp</code>，<code>bind</code>，<code>listen</code>。</li><li><code>accept</code>：接受进来的连接（可以在发起进来的连接之前或之后执行）。</li><li><code>connect &lt;hostname&gt; &lt;port #&gt;</code>：等效于 <code>socklab</code>，<code>sock tcp</code>，<code>bind</code>，<code>connect</code>。</li><li><code>close</code>：关闭连接。</li><li><code>read &lt;byte #&gt;</code>：从套接字中读取 n 字节。</li><li><code>write</code>：（例如，<code>write ciao</code>、<code>write #10</code>）向套接字写入 &quot;ciao&quot; 或 10 个字节。</li></ul><h4 id="nat-防火墙" tabindex="-1">NAT/防火墙 <a class="header-anchor" href="#nat-防火墙" aria-label="Permalink to “NAT/防火墙”">​</a></h4><ul><li><code>rm /etc/resolv.conf</code>：禁止地址解析，保证你的过滤和防火墙规则正确工作。</li><li><code>ipnat -f file_name</code>：将过滤规则写入文件。</li><li><code>ipnat -l</code>：显示活动的规则列表。</li><li><code>ipnat -C -F</code>：重新初始化规则表。</li><li><code>map em0 192.168.1.0/24 -&gt; 195.221.227.57/32 em0</code>：将 IP 地址映射到接口。</li><li><code>map em0 192.168.1.0/24 -&gt; 195.221.227.57/32 portmap tcp/udp 20000:50000</code>：带端口号的映射。</li><li><code>ipf -f file_name</code>：将过滤规则写入文件。</li><li><code>ipf -F -a</code>：重置规则表。</li><li><code>ipfstat -I</code>：当与 -s 选项合用时列出活动的状态条目（LCTT 译注：原文存疑）。</li></ul><p>希望这份基础的 Linux 网络命令合集对你有用。欢迎各种问题和建议。</p><hr>',21)),l("p",null,[e[9]||(e[9]=o("via: ",-1)),t(i,{href:"https://itsfoss.com/basic-linux-networking-commands"},{default:d(()=>[...e[8]||(e[8]=[o("https://itsfoss.com/basic-linux-networking-commands",-1)])]),_:1})]),l("p",null,[e[13]||(e[13]=o("作者：",-1)),t(i,{href:"https://itsfoss.com/author/abhishek/"},{default:d(()=>[...e[10]||(e[10]=[o("Abhishek Prakash",-1)])]),_:1}),e[14]||(e[14]=o(" 译者：",-1)),t(i,{href:"https://github.com/bianjp"},{default:d(()=>[...e[11]||(e[11]=[o("bianjp",-1)])]),_:1}),e[15]||(e[15]=o(" 校对：",-1)),t(i,{href:"https://github.com/wxy"},{default:d(()=>[...e[12]||(e[12]=[o("wxy",-1)])]),_:1})]),l("p",null,[e[18]||(e[18]=o("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...e[16]||(e[16]=[o("LCTT",-1)])]),_:1}),e[19]||(e[19]=o(" 原创编译，",-1)),t(i,{href:"https://linux.cn/"},{default:d(()=>[...e[17]||(e[17]=[o("Linux中国",-1)])]),_:1}),e[20]||(e[20]=o(" 荣誉推出",-1))])])}const k=n(u,[["render",p]]);export{b as __pageData,k as default};
